using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;
using System.Collections.Generic;
namespace Ara {
 public static class MobileTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(15);GridEngine.Ensure(s,d);return s;}
  static PhoneCommand Cmd(MainForm f,string op,int first=96,int last=98,int lane=1){return new PhoneCommand{op=op,lane=lane,first=first,last=last,date=f.Day.Date,baseRevision=f.PhoneSnapshot(f.Day.Date).revision,requestId=Guid.NewGuid().ToString("N")};}
  static void With(string dir,string name,Action<MainForm> test){using(var f=new MainForm(new Store(Path.Combine(dir,"phone-"+name+".json")),New(),true)){f.Show();Application.DoEvents();try{test(f);}finally{f.Quit();}}}
  static Dictionary<string,string> Headers(MobileServer server,bool auth=true){var h=new Dictionary<string,string>{{"host","127.0.0.1:"+server.Port}};if(auth)h["authorization"]="Bearer "+server.Token;return h;}
  public static void Run(Action<string,Action> check,string dir){
   check("phone: schedule crosses midnight with one sleep marker and twelve dim slots",()=>{var s=New();var d=s.Days[0];var v=PhoneCodec.Snapshot(s,d.Date);Assert(v.wake==90&&v.sleep==189&&v.target==189&&v.lightsStart==177,"15:00 to next 07:30");Assert(v.planned.Count==14&&v.actual.Count==0&&v.sleep-v.lightsStart==12,"display-only sleep and lighting");});
   check("phone: snapshot excludes private notes and task metadata from revision",()=>{var s=New();var d=s.Days[0];var a=PhoneCodec.Snapshot(s,d.Date);d.Note="secret-note";s.WorkLink="secret-work-path";s.Tasks.Add(new Todo{Id="t",Text="private-task",Group="작업"});var b=PhoneCodec.Snapshot(s,d.Date);string text=Encoding.UTF8.GetString(PhoneCodec.Json(b));Assert(a.revision==b.revision&&!text.Contains("secret")&&!text.Contains("private-task"),"only timetable shared");});
   check("phone: numeric score and optional category preserve total through disk save",()=>With(dir,"score",f=>{var c=Cmd(f,"score");c.score=4;f.PhoneApply(c);c=Cmd(f,"category");c.category="작업";var view=f.PhoneApply(c);Assert(view.total==12&&view.actual.All(x=>x.category=="작업"),"three slots times four");var loaded=f.Store.Load();Assert(GridEngine.Total(loaded.GetDay(PhoneCodec.Date(f.Day.Date)))==12,"durable score");}));
   check("phone: duplicate requests persistently deduplicate after reload",()=>With(dir,"dedup",f=>{var c=Cmd(f,"score");c.score=3;var view=f.PhoneApply(c);f.Data=f.Store.Load();f.Day=f.Data.GetDay(PhoneCodec.Date(c.date));var again=f.PhoneApply(c);Assert(view.revision==again.revision&&again.total==9&&f.Data.RemoteReceipts.Count==1,"idempotent even with old revision");}));
   check("phone: reused request ID with different contents rejects before mutation",()=>With(dir,"duplicate",f=>{var c=Cmd(f,"score");c.score=3;f.PhoneApply(c);c.score=9;bool failed=false;try{f.PhoneApply(c);}catch(InvalidDataException){failed=true;}Assert(failed&&f.PhoneSnapshot(c.date).total==9,"no duplicate rewrite");}));
   check("phone: stale PC revision produces conflict without changing stored records",()=>With(dir,"conflict",f=>{var stale=Cmd(f,"score");stale.score=5;var fresh=Cmd(f,"category");fresh.category="학습";f.PhoneApply(fresh);var before=PhoneCodec.Hash(PhoneCodec.Json(f.Data));bool conflict=false;try{f.PhoneApply(stale);}catch(SyncConflict){conflict=true;}Assert(conflict&&before==PhoneCodec.Hash(PhoneCodec.Json(f.Data)),"CAS rejects stale selection");}));
   check("phone: plan meal copied to actual drives schedule and sleep",()=>With(dir,"copy",f=>{var source=f.PhoneSnapshot(f.Day.Date).planned.First(x=>x.mealId=="b1");var c=Cmd(f,"copy",source.start+6,source.start+8);c.sourceId=source.id;var view=f.PhoneApply(c);Assert(view.actual.Single().mealId=="b1"&&view.actual.Single().start==source.start+6,"meal recognized");Assert(view.planned.FirstOrDefault(x=>x.mealId=="b10")!=null&&view.sleep<=view.target,"rebalanced");}));
   check("phone: move and Delete operate on whole actual blocks",()=>With(dir,"delete",f=>{var c=Cmd(f,"category");c.category="학습";var v=f.PhoneApply(c);c=Cmd(f,"move",105,105);c.id=v.actual.Single().id;v=f.PhoneApply(c);Assert(v.actual.Single().start==105&&v.actual.Single().count==3,"whole block moved");c=Cmd(f,"delete",106,106);v=f.PhoneApply(c);Assert(v.actual.Count==0,"one clicked cell removes entire block");}));
   check("phone: upper meal deletion removes meal prep too",()=>With(dir,"delete-plan",f=>{var source=f.PhoneSnapshot(f.Day.Date).planned.First(x=>x.mealId=="b10");f.PhoneApply(Cmd(f,"delete",source.start,source.start,0));Assert(!f.Day.GridBase.Any(x=>x.MealId=="b10"||x.PrepFor=="b10"),"prep removed");}));
   check("phone: wake by selecting a cell generates next-day-safe schedule",()=>With(dir,"wake",f=>{var c=Cmd(f,"category",90,90);c.category="기상";var view=f.PhoneApply(c);Assert(view.wake==90&&view.actual.Single().category=="기상"&&view.planned.First(x=>x.mealId=="b1").start==93,"wake and first meal");Engine.Validate(f.Data);}));
   check("phone: undo restores timetable while preserving PC note and receipts",()=>With(dir,"undo",f=>{var c=Cmd(f,"score");c.score=5;f.PhoneApply(c);((TextBox)typeof(MainForm).GetField("note",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(f)).Text="PC note";var undo=Cmd(f,"undo");undo.sourceId=c.requestId;var v=f.PhoneApply(undo);Assert(v.total==0&&f.Day.Note=="PC note"&&f.Data.RemoteReceipts.Count==2,"timetable-only undo");}));
   check("phone: undo cannot restore a different date over today's timetable",()=>With(dir,"undo-date",f=>{var c=Cmd(f,"score");c.score=5;f.PhoneApply(c);var undo=Cmd(f,"undo");undo.date=PhoneCodec.Date(c.date).AddDays(1).ToString("yyyy-MM-dd");undo.baseRevision=f.PhoneSnapshot(undo.date).revision;undo.sourceId=c.requestId;bool failed=false;try{f.PhoneApply(undo);}catch(InvalidDataException){failed=true;}Assert(failed&&f.Data.Days.Count==1&&f.PhoneSnapshot(c.date).total==15,"date cannot cross");}));
   check("phone: invalid ranges, categories and meal IDs leave disk unchanged",()=>With(dir,"invalid",f=>{f.Store.Save(f.Data);var disk=File.ReadAllBytes(f.Store.PathName);foreach(int kind in new[]{0,1,2}){var c=Cmd(f,"detail");c.category=kind==1?"bad":"식사";c.mealId=kind==2?"bad":"";if(kind==0)c.last=288;bool bad=false;try{f.PhoneApply(c);}catch(InvalidDataException){bad=true;}Assert(bad&&disk.SequenceEqual(File.ReadAllBytes(f.Store.PathName)),"invalid packet atomic");}}));
   check("phone HTTP: unauthorized, foreign origins and arbitrary file paths are blocked",()=>With(dir,"security",f=>{using(var server=new MobileServer(f,18765)){var h=Headers(server,false);Assert(server.Dispatch("GET","/api/day?date="+f.Day.Date,h,new byte[0],"127.0.0.1").status==401,"auth required");h["origin"]="https://evil.example";Assert(server.Dispatch("GET","/",h,new byte[0],"127.0.0.1").status==403,"origin blocked");h.Remove("origin");h["host"]="evil.example";Assert(server.Dispatch("GET","/",h,new byte[0],"127.0.0.1").status==400,"DNS rebinding blocked");h=Headers(server);Assert(server.Dispatch("GET","/../state.json",h,new byte[0],"127.0.0.1").status==404,"whitelist files only");}}));
   check("phone HTTP: pair code is rate limited and authorized API returns only timetable",()=>With(dir,"pair",f=>{using(var server=new MobileServer(f,18765)){var h=Headers(server,false);for(int i=0;i<5;i++)Assert(server.Dispatch("POST","/api/pair",h,PhoneCodec.Json(new PairRequest{code="wrong"}),"10.0.0.9").status==401,"denied");Assert(server.Dispatch("POST","/api/pair",h,PhoneCodec.Json(new PairRequest{code=server.Code}),"10.0.0.9").status==429,"limited");var reply=server.Dispatch("POST","/api/pair",h,PhoneCodec.Json(new PairRequest{code=server.Code}),"10.0.0.8");Assert(reply.status==200&&PhoneCodec.Read<PairReply>(reply.body).token==server.Token,"correct code");reply=server.Dispatch("GET","/api/day?date="+f.Day.Date,Headers(server),new byte[0],"127.0.0.1");Assert(PhoneCodec.Read<PhoneDay>(reply.body).wake==90,"authenticated view");}}));
   check("phone HTTP: real TCP request enters UI thread and returns durable score",()=>With(dir,"tcp",f=>{using(var server=new MobileServer(f,18765)){server.Start(false);var command=Cmd(f,"score");command.score=7;var task=Task.Run(()=>{var request=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:18765/api/command");request.Proxy=null;request.Method="POST";request.Timeout=8000;request.ContentType="application/json";request.Headers["Authorization"]="Bearer "+server.Token;var body=PhoneCodec.Json(command);request.ContentLength=body.Length;using(var stream=request.GetRequestStream())stream.Write(body,0,body.Length);using(var response=request.GetResponse())using(var stream=response.GetResponseStream())using(var memory=new MemoryStream()){stream.CopyTo(memory);return PhoneCodec.Read<PhoneDay>(memory.ToArray());}});var limit=DateTime.UtcNow.AddSeconds(9);while(!task.IsCompleted&&DateTime.UtcNow<limit){Application.DoEvents();System.Threading.Thread.Sleep(5);}Assert(task.IsCompleted&&task.Result.total==21,"HTTP UI roundtrip");Assert(GridEngine.Total(f.Store.Load().GetDay(PhoneCodec.Date(f.Day.Date)))==21,"TCP write persisted");server.Disable();Assert(!server.Running&&!PhoneCodec.Read<PairingConfig>(File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(f.Store.PathName),"mobile-pairing.json"))).enabled,"stop option persisted");}}));
   check("adaptive: yogurt precedes weight shortening and second meal gap remains 150 minutes",()=>{var s=New();var d=s.Days[0];d.Records.Add(new CellBlock{Id="r",MealId="b1",Category="식사",Start=d.Wake.AddMinutes(510),Count=3});var p=GridEngine.Build(s,d);var weight=p.Blocks.Single(x=>x.Category=="웨이트");Assert(weight.Count==3&&p.Overflow==90&&!p.Blocks.Any(x=>x.MealId=="b16"),"yogurt then minimum weights; post-meal rest leaves honest overrun");Assert(weight.Start>=p.Blocks.First(x=>x.MealId=="b6").Start.AddMinutes(150),"two hours after meal end");Assert(p.Changes.FindIndex(x=>x.Contains("요거트")&&x.Contains("제외"))<p.Changes.FindIndex(x=>x.Contains("웨이트 −")),"priority order");});
   check("adaptive: all first-meal delays keep minimum second meal to weights interval",()=>{for(int delay=0;delay<=800;delay+=10){var s=New();var d=s.Days[0];d.Records.Add(new CellBlock{Id="r",MealId="b1",Category="식사",Start=d.Wake.AddMinutes(30+delay),Count=3});var p=GridEngine.Build(s,d);Assert(p.Blocks.First(x=>x.Category=="웨이트").Start>=p.Blocks.First(x=>x.MealId=="b6").Start.AddMinutes(150),"delay "+delay);}});
  }
 }
}
